262	   * What Moneo needs to answer one request on its own: the requests still being answered separately, the call so far
263	   * to resolve "that" or "also", and what this call has already answered.
264	   */
265	  private brief() {
266	    return {
267	      via: "call", input: "voice",
268	      runningTasks: this.running.slice(-5).map(task => ({ requestId: task.requestId, text: task.text.slice(0, 300) })),
269	      recentTurns: this.captions.slice(-6).map(caption => ({ role: caption.role, text: caption.text.slice(-300) })),
270	      answered: this.tasks.flatMap(task => {
271	        const answer = this.answers.get(task.requestId);
272	        return answer ? [{ requestId: task.requestId, text: task.text.slice(0, 150), answer: answer.slice(0, 300) }] : [];
