277	  private start(text: string, delegationId: string | null) {
278	    const requestId = this.newId();
279	    const context = this.brief();
280	    this.tasks = [...this.tasks, { requestId, text, step: "starting", status: "running", delegationId, cards: [] }];
281	    this.startedAt.set(requestId, this.now());
282	    this.deps.onChange();
283	    this.watchSlow(requestId);
284	    void this.run(requestId, text, context);
285	    return requestId;
