288	  private async run(requestId: string, text: string, context: ReturnType<VoiceCallController["brief"]>) {
289	    const label = `"${text.slice(0, 120)}"`;
290	    // Read when needed: a late hand-off can take a request over while it runs.
291	    const via = () => this.tasks.find(item => item.requestId === requestId)?.delegationId ?? null;
292	    try {
293	      const result = await this.deps.ask({ conversationId: this.deps.conversationId, requestId, message: text.slice(0, 4000), context }, event => {
294	        // A stopped request's last progress notes are not shown or said.
295	        if (event.type !== "tool" || event.state !== "running" || this.tasks.find(item => item.requestId === requestId)?.status === "canceled") return;
296	        if (event.name === "call_replace_task") this.replaced((event.input as { requestId?: unknown } | undefined)?.requestId);
297	        const step = stepFor(event.name);
298	        this.update(requestId, { step });
299	        if (via()) this.deps.send({ type: "session.thinking.append", delegation_id: via(), content: `Working on ${label}: ${step}.` });
300	      });
301	      const task = this.tasks.find(item => item.requestId === requestId);
302	      // Canceled from the list, or stopped because a correction replaced it: nothing to say.
303	      if (task?.status === "canceled") return;
304	      if (result.status === 409) { this.update(requestId, { status: "canceled", step: "stopped" }); return; }
305	      if (!result.ok || !result.body.answer) throw new Error(result.body.error ?? "No answer");
306	      const cards = answerCards(result.body.answer);
307	      this.answers.set(requestId, spokenAnswer(result.body.answer));
308	      this.update(requestId, { status: "done", step: "answered", cards });
309	      this.deps.onAnswer?.(text, result.body as ChatAnswer);
310	      // A typed request has no hand-off to answer through, so the result says outright that it is to be spoken.
311	      const delegationId = via();
312	      this.deliver(requestId, delegationId, [`Result for ${label}${delegationId ? "" : " (typed by the user in the call; say the result to them now, in the language of their quoted words)"}: ${spokenAnswer(result.body.answer)}`,
313	        cards.length ? `${cards.length} card${cards.length > 1 ? "s" : ""} on screen to tap; nothing is saved until then.` : ""].filter(Boolean).join(" "));
314	    } catch {
315	      if (this.tasks.find(item => item.requestId === requestId)?.status === "canceled") return;
316	      this.update(requestId, { status: "failed", step: "failed" });
317	      this.deliver(requestId, via(), `Moneo couldn't get an answer for ${label}. Tell the user briefly and ask if they want you to try again.`);
318	    }
319	  }
