321	  /** One short spoken update for a task that runs long, once nobody is talking. Re-checks every second; ends when the task does. */
322	  private watchSlow(requestId: string, delay = SLOW_TASK_MS) {
323	    this.schedule(() => {
324	      const task = this.tasks.find(item => item.requestId === requestId);
325	      if (task?.status !== "running" || this.announced.has(requestId)) return;
326	      // Never in the middle of saying a result, or before one waiting to be said.
327	      if (this.speaking() || !this.resultSaid() || this.cut || this.outbox.length) return this.watchSlow(requestId, 1000);
328	      this.stillWorking([task]);
329	    }, delay);
330	  }
331	
332	  private stillWorking(tasks: CallTask[]) {
333	    tasks.forEach(task => this.announced.add(task.requestId));
334	    const names = tasks.map(task => `"${task.text.slice(0, 120)}" (${task.step})`).join(", ");
335	    this.deps.send({ type: "session.commentary.append", delegation_id: tasks[0].delegationId,
336	      content: `Still working on ${names}. Say so in a few words${tasks.some(task => task.delegationId) ? "" : ", in the language of their quoted words"}.` });
337	  }
338	
339	  /** Results queue in the order they finish. */
340	  private deliver(requestId: string, delegationId: string | null, content: string) {
341	    this.outbox.push({ requestId, delegationId, content });
342	    this.flush();
343	  }
344	
345	  /**
346	   * A correction is replacing an earlier request: its result is not said, so Moneo never gives the old answer before
347	   * the corrected one. The server stops it or dismisses its cards.
348	   */
349	  private replaced(requestId: unknown) {
350	    const task = this.tasks.find(item => item.requestId === requestId);
351	    if (!task || task.status === "failed" || task.status === "canceled") return;
352	    // Its cards are dismissed by the server, so they leave the tray.
353	    this.drop(task.requestId, { status: "canceled", step: "replaced", cards: [] });
354	  }
355	
356	  /**
357	   * Hands over the next result once Moneo has said the previous one and nobody is talking. A result never says what
358	   * else is still running: by the time Moneo reaches the end of it, that may have finished too.
359	   */
360	  /**
361	   * A later request still choosing its first step may be a correction ("no, I meant this month") that replaces this
362	   * result, which it does first: the result waits a moment for it, so the old answer isn't said before the new one.
363	   */
364	  private mayBeReplaced(requestId?: string) {
365	    // Words GPT-Live said it is on, about to start as their own request, may be that correction too.
366	    if (this.takenOn && this.lastDelegation && plain(this.heard.map(piece => piece.text).join("")).split(/\s+/).length >= 3) return true;
367	    const index = this.tasks.findIndex(task => task.requestId === requestId);
368	    return index >= 0 && this.tasks.slice(index + 1).some(task => task.status === "running" && task.step === "starting"
369	      && this.now() - (this.startedAt.get(task.requestId) ?? -Infinity) < REPLACE_WAIT_MS);
370	  }
371	
372	  private flush() {
373	    if (this.flushing || !this.outbox.length || this.cut) return;
374	    if (this.speaking("user") || this.now() - this.lastUserSpeech < USER_PAUSE_MS || !this.resultSaid() || this.mayBeReplaced(this.outbox[0].requestId)) {
375	      this.flushing = true;
376	      this.schedule(() => { this.flushing = false; this.flush(); }, 300);
377	      return;
378	    }
379	    const { requestId, delegationId, content } = this.outbox.shift()!;
380	    this.current = { requestId, delegationId, content, at: this.now() };
381	    // It is no longer waiting to be said, so it can't be stopped from the list.
382	    this.deps.onChange();
383	    this.deps.log?.(`handed over: ${content.slice(0, 60)}`);
384	    this.deps.send({ type: "session.commentary.append", delegation_id: delegationId, content: `${content} ${ONLY_THIS_RESULT}` });
385	    this.flush();
386	  }
387	
388	  /**
389	   * Once the user has finished and Moneo has answered them (or had a few seconds to), Moneo is asked to finish the
390	   * result it was cut off in before any other. A short "mm-hm" over it is not an interruption.
391	   */
392	  private resume() {
393	    this.schedule(() => {
394	      const cut = this.cut;
395	      if (!cut) return;
396	      if (this.speaking() || this.now() - this.lastUserSpeech < USER_PAUSE_MS
397	        || (this.lastMoneo <= this.lastUserSpeech && this.now() - this.lastUserSpeech < RESUME_AFTER_MS)) return this.resume();
398	      this.cut = null;
399	      // A "mm-hm" is not an interruption, and "stop" or "next one" drops the result for the next.
400	      const resume = cut.words.trim().split(/\s+/).length >= 3 && !isSkip(cut.words);
401	      this.deps.log?.(resume ? "resuming the cut-off result" : "not resuming the cut-off result");
402	      if (resume) this.outbox.unshift({ requestId: cut.requestId, delegationId: cut.delegationId,
403	        content: `The user talked over you while you were giving this result. If you hadn't finished it, first say in a few words that you're going back to it (like "Anyway, back to your September spending…"), then finish the part you hadn't said yet, without repeating what you already said; if you had, say nothing more about it. ${cut.content}` });
404	      this.flush();
405	    }, 300);
406	  }
407	
408	  /** Marks a task canceled and drops its result if it is still to be said; the caller asks the server to stop a running one. */
409	  cancel(requestId: string) { this.drop(requestId, { status: "canceled", step: "stopped" }); }
410	
411	  /** A result that is not to be said: neither waiting in line nor, if the user cut it off, the rest of it. */
412	  private drop(requestId: string, change: Partial<CallTask>) {
413	    this.outbox = this.outbox.filter(item => item.requestId !== requestId);
414	    if (this.cut?.requestId === requestId) this.cut = null;
415	    this.update(requestId, change);
416	  }
417	}
