394	export async function PATCH(request: Request) {
395	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
396	  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
397	  const parsed = z.object({ requestId: z.uuid() }).strict().safeParse(await request.json().catch(() => null));
398	  if (!parsed.success) return Response.json({ error: "Invalid cancellation" }, { status: 400 });
399	  const result = await context.supabase.rpc("cancel_chat_request", { p_request_id: parsed.data.requestId });
400	  if (result.error) return Response.json({ error: result.error.message }, { status: result.error.code === "P0002" ? 404 : 400 });
401	  return Response.json({ status: result.data });
402	}
