3	import { useRef, useState } from "react";
4	import type { FollowUp } from "./follow-ups";
5	import type { ChatAttachment } from "./chat-attachments";
6	
7	export type ChatAnswer = { answer: string; conversationId: string; toolsUsed?: string[]; followUps?: FollowUp[] };
8	export type ChatStreamEvent =
9	  | { type: "started" }
10	  | { type: "tool"; id?: string; name: string; state: "running" | "done" | "failed"; input?: unknown; output?: string }
11	  | { type: "plan"; steps: string[] }
12	  | { type: "steered"; steers: { id: string; content: string }[] }
13	  | { type: "delta"; text: string }
14	  | ({ type: "answer" } & ChatAnswer)
15	  | { type: "result"; status: number; body: unknown };
16	
17	/** Reads the opt-in NDJSON stream, or a plain JSON response, into the final status and body. */
18	export async function readResponse(response: Response, onEvent: (event: ChatStreamEvent) => void): Promise<{ ok: boolean; status: number; body: { error?: string } & Partial<ChatAnswer> }> {
19	  if (!response.headers.get("content-type")?.includes("application/x-ndjson") || !response.body) return { ok: response.ok, status: response.status, body: await response.json() };
20	  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
21	  let buffer = "";
22	  for (;;) {
23	    const { value, done } = await reader.read();
24	    buffer += value ?? "";
25	    const lines = buffer.split("\n");
26	    buffer = done ? "" : lines.pop()!;
27	    for (const line of lines.filter(Boolean)) {
28	      const event = JSON.parse(line) as ChatStreamEvent;
29	      if (event.type === "result") return { ok: event.status < 400, status: event.status, body: event.body as { error?: string } };
30	      onEvent(event);
31	    }
32	    if (done) throw new Error("The answer stream ended early; reload to see whether it was saved");
33	  }
34	}
