36	export function useChatRequest() {
37	  const active = useRef<{ requestId: string; controller: AbortController } | null>(null);
38	  const [status, setStatus] = useState<"idle" | "running" | "completed" | "failed" | "canceled">("idle");
39	  const [error, setError] = useState("");
40	  const [conversationId, setConversationId] = useState<string | null>(null);
41	
42	  async function send(payload: { conversationId: string; message: string; context?: Record<string, unknown>; attachments?: ChatAttachment[] }, onEvent?: (event: ChatStreamEvent) => void) {
43	    if (active.current) return null;
44	    const run = { requestId: crypto.randomUUID(), controller: new AbortController() };
45	    active.current = run;
46	    setConversationId(payload.conversationId);
47	    setStatus("running");
48	    setError("");
49	    try {
50	      const response = await fetch("/api/chat", { method: "POST", headers: { "Content-Type": "application/json", Accept: "application/x-ndjson, application/json" },
51	        signal: run.controller.signal, body: JSON.stringify({ ...payload, requestId: run.requestId }) });
52	      // Events from a canceled run are never shown.
53	      const result = await readResponse(response, event => { if (active.current === run) onEvent?.(event); });
54	      if (active.current !== run) return null;
55	      if (!result.ok) throw new Error(result.body.error ?? "Could not answer");
56	      setStatus("completed");
57	      return result.body as ChatAnswer;
58	    } catch (cause) {
59	      if (active.current === run) { setStatus("failed"); setError(cause instanceof Error ? cause.message : "Could not answer"); }
60	      return null;
61	    } finally { if (active.current === run) active.current = null; }
62	  }
63	
64	  async function cancel() {
65	    const run = active.current;
66	    if (!run) return;
67	    try {
68	      let response: Response | undefined;
69	      // Cancellation can arrive before the server has claimed this request.
70	      for (let attempt = 0; attempt < 10; attempt++) {
71	        response = await fetch("/api/chat", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ requestId: run.requestId }) });
72	        if (response.status !== 404) break;
73	        await new Promise(resolve => setTimeout(resolve, 100));
74	      }
75	      const result = await response!.json();
76	      if (!response!.ok) throw new Error(result.error ?? "Could not cancel; try again");
77	      if (result.status === "canceled" && active.current === run) {
78	        active.current = null;
79	        run.controller.abort();
80	        setStatus("canceled");
81	      }
82	    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not cancel; try again"); }
83	  }
84	
85	  /** The in-flight request, which steer messages target. */
86	  const requestId = () => active.current?.requestId ?? null;
87	  return { send, cancel, requestId, status, error, busy: status === "running", conversationId };
88	}
