100	        .then(async response => { const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error ?? "Could not start the call"); return body.sdp as string; });
101	      answer.catch(() => {});
102	      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } });
103	      if (closed) { stream.getTracks().forEach(track => track.stop()); return; }
104	      live.set({ mic: stream });
105	      context = new AudioContext();
106	      live.set({ micLevel: analyser(stream) });
107	      await slot.sender.replaceTrack(stream.getAudioTracks()[0]);
108	      const sdp = await answer;
109	      if (!closed) await pc.setRemoteDescription({ type: "answer", sdp });
110	    }
111	    const analyser = (source: MediaStream) => { const node = context!.createAnalyser(); node.fftSize = 512; context!.createMediaStreamSource(source).connect(node); return node; };
112	    /** Hanging up saves the call in the chat; keepalive lets it finish even if the tab is closing. */
113	    function saveRecord() {
114	      const transcript = boundTranscript(controller.captions);
115	      if (live.startedAt === null || !transcript.length) return;
116	      const seconds = Math.min(86_400, Math.round((Date.now() - live.startedAt) / 1000));
117	      live.startedAt = null;
118	      // Answers that land after hang-up are saved by the server and shown inside the call.
119	      const finished = live.onEnded;
120	      live.set({ onAnswer: undefined });
121	      void fetch("/api/voice/calls", { method: "POST", keepalive: true, headers: { "Content-Type": "application/json" },
122	        body: JSON.stringify({ id: live.callId, conversationId, durationSeconds: seconds, transcript,
123	          tasks: controller.tasks.slice(-30).map(task => ({ requestId: task.requestId, text: task.text.slice(0, 300), status: task.status })) }) })
124	        .then(response => { if (response.ok) finished?.(); }, () => {});
125	    }
126	    connect().catch(cause => { if (!closed) { setStatus("error"); setError(failure(cause)); } });
127	    // Both voices, metered: what the user actually hears, and whether they talked over it, decide when a result has been said.
128	    const buffer = new Uint8Array(512);
129	    let moneoOn = false, micOn = false, talking = false;
130	    const meter = setInterval(() => {
131	      const moneo = level(live.moneoLevel, buffer) > 0.02, mic = level(live.micLevel, buffer) > 0.08;
132	      audio.volume = playback.volume(Date.now(), mic, moneo);
133	      if (moneo && audio.volume > 0) controller.heardMoneo();
134	      if (mic) controller.heardUser();
135	      if (trace && moneo !== moneoOn) trace(moneo ? "Moneo audible" : "Moneo quiet");
136	      if (trace && mic !== micOn) trace(mic ? "mic loud" : "mic quiet");
137	      moneoOn = moneo; micOn = mic;
138	      // The call screen shows when Moneo is talking; it re-renders only when that changes.
139	      if (controller.answering !== talking) { talking = !talking; render(); }
140	    }, 100);
141	    document.addEventListener("visibilitychange", lock);
142	    return () => {
143	      closed = true;
144	      clearInterval(meter);
145	      saveRecord();
146	      document.removeEventListener("visibilitychange", lock);
147	      try { if (live.channel?.readyState === "open") live.channel.send(JSON.stringify({ type: "session.close" })); } catch { /* already closed */ }
148	      live.set({ channel: null, micLevel: null, moneoLevel: null });
149	      live.mic?.getTracks().forEach(track => track.stop());
150	      pc?.close();
151	      audio.srcObject = null;
152	      void context?.close();
153	      void wakeLock?.release();
154	    };
155	  }, [controller, conversationId, live]);
156	
157	  function toggleMute() {
158	    const next = !muted;
159	    live.mic?.getAudioTracks().forEach(track => { track.enabled = !next; });
160	    setMuted(next);
161	  }
162	
163	  async function cancel(requestId: string) {
164	    const running = controller.running.some(task => task.requestId === requestId);
165	    controller.cancel(requestId);
166	    // An answered request has nothing left to stop on the server.
167	    if (!running) return;
168	    // Cancellation can arrive before the server has claimed the request.
169	    for (let attempt = 0; attempt < 10; attempt++) {
170	      const response = await fetch("/api/chat", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ requestId }) }).catch(() => null);
171	      if (response?.status !== 404) break;
172	      await new Promise(resolve => setTimeout(resolve, 100));
173	    }
174	    live.aborts.get(requestId)?.abort();
175	  }
176	
177	  /** Current loudness of the user's mic and of Moneo's voice, for the orb; read every frame without re-rendering. */
178	  const [levels] = useState(() => {
179	    const buffer = new Uint8Array(512);
180	    return () => ({ mic: level(live.micLevel, buffer), moneo: level(live.moneoLevel, buffer) });
181	  });
182	
183	  return {
184	    status, error: error || controller.error, muted, toggleMute, cancel, levels,
185	    captions: controller.captions, tasks: controller.tasks, cards: controller.cards, unsaid: controller.unsaid,
186	    typed: (text: string) => controller.typed(text),
187	    /** Moneo is answering or working; used for the orb's thinking state. */
188	    thinking: controller.running.length > 0,
189	    /** Moneo is talking, or about to go on with its next result. */
190	    talking: controller.answering,
191	  };
192	}
