1	import type { SupabaseClient } from "@supabase/supabase-js";
2	import { z } from "zod";
3	import { STANDALONE_KINDS } from "./open-proposals";
4	import { callTaskSchema, callTurnSchema, type CallTurn } from "./voice-call-record";
5	
6	export type CallExchange = { id: string; role: string; content: string; created_at: string };
7	/** A finished call as the chat shows it: the summary, its cards, the transcript and the chat messages it produced. */
8	export type CallCard = {
9	  id: string; durationSeconds: number; summary: string | null; summaryStatus: "pending" | "done" | "failed";
10	  transcript: CallTurn[];
11	  /** Requests still running when the call ended, with where they stand now. */
12	  unfinished: { text: string; status: "running" | "completed" | "failed" | "canceled" }[];
13	  /** Card ids made during the call, oldest first; each card loads its own current state. */
14	  cards: string[];
15	  exchanges: CallExchange[];
16	};
17	type CallRow = { id: string; duration_seconds: number; transcript: unknown; tasks: unknown; request_ids: string[]; summary: string | null; summary_status: CallCard["summaryStatus"]; created_at: string };
18	
19	type CallStub = Pick<CallRow, "id" | "request_ids" | "created_at">;
20	// A conversation rarely has more than a handful of calls; the list holds ids only, never transcripts.
21	const STUB_LIMIT = 200;
22	
23	/** Which calls a conversation has and the requests each started. Start it beside the page of messages so it adds no round trip. */
24	export const callStubs = (supabase: SupabaseClient, workspace: string, conversation: string) =>
25	  Promise.resolve(supabase.from("voice_calls").select("id,request_ids,created_at").eq("workspace_id", workspace).eq("conversation_id", conversation)
26	    .order("created_at", { ascending: false }).limit(STUB_LIMIT));
27	
28	/** Calls to show on a page of messages (saved within its time range) and the request ids whose messages they replace. */
29	export async function loadCalls(supabase: SupabaseClient, workspace: string, conversation: string, stubs: Awaited<ReturnType<typeof callStubs>>, page: { requestIds: string[]; from?: string; to?: string }) {
30	  if (stubs.error) throw new Error("Could not load calls. Try again.");
31	  const all = (stubs.data ?? []) as CallStub[];
32	  const inPage = (stub: CallStub) => (!page.from || Date.parse(stub.created_at) >= Date.parse(page.from)) && (!page.to || Date.parse(stub.created_at) < Date.parse(page.to));
33	  const shown = all.filter(inPage).slice(0, 20);
34	  // A call whose card is on a newer page can still own messages on this one.
35	  const own = new Set(page.requestIds);
36	  const hidden = new Set([...shown, ...all.filter(stub => stub.request_ids.some(id => own.has(id)))].flatMap(stub => stub.request_ids));
37	  if (!shown.length) return { hidden, items: [] };
38	  const called = await supabase.from("voice_calls").select("id,duration_seconds,transcript,tasks,request_ids,summary,summary_status,created_at")
39	    .eq("workspace_id", workspace).eq("conversation_id", conversation).in("id", shown.map(stub => stub.id)).order("created_at", { ascending: false });
40	  if (called.error) throw new Error("Could not load calls. Try again.");
41	  const rows = (called.data ?? []) as CallRow[];
42	
43	  const requestIds = [...new Set(rows.flatMap(row => row.request_ids))];
44	  const running = [...new Set(rows.flatMap(row => parseTasks(row.tasks).filter(task => task.status === "running").map(task => task.requestId)))];
45	  const [messages, cards, requests] = await Promise.all([
46	    requestIds.length ? supabase.from("messages").select("id,role,content,created_at,request_id,reply_to").eq("workspace_id", workspace).eq("conversation_id", conversation)
47	      .or(`request_id.in.(${requestIds.join(",")}),reply_to.in.(${requestIds.join(",")})`).order("created_at") : null,
48	    requestIds.length ? supabase.from("agent_proposals").select("id,chat_request_id").eq("workspace_id", workspace).in("chat_request_id", requestIds).in("kind", STANDALONE_KINDS).order("created_at") : null,
49	    running.length ? supabase.from("chat_requests").select("id,status").eq("workspace_id", workspace).in("id", running) : null,
50	  ]);
51	  if (messages?.error || cards?.error || requests?.error) throw new Error("Could not load calls. Try again.");
52	  const status = new Map((requests?.data ?? []).map(row => [row.id as string, row.status as CallCard["unfinished"][number]["status"]]));
53	
54	  const items = rows.map(row => {
55	    const own = new Set(row.request_ids);
56	    const tasks = parseTasks(row.tasks);
57	    const transcript = z.array(callTurnSchema).safeParse(row.transcript);
58	    return {
59	      id: row.id, role: "assistant", content: "", created_at: row.created_at,
60	      call: {
61	        id: row.id, durationSeconds: row.duration_seconds, summary: row.summary, summaryStatus: row.summary_status,
62	        transcript: transcript.success ? transcript.data : [],
63	        unfinished: tasks.filter(task => task.status === "running").map(task => ({ text: task.text, status: status.get(task.requestId) ?? "running" })),
64	        cards: (cards?.data ?? []).filter(card => own.has(card.chat_request_id as string)).map(card => card.id as string),
65	        exchanges: (messages?.data ?? []).filter(message => own.has((message.request_id ?? message.reply_to) as string))
66	          .map(({ id, role, content, created_at }) => ({ id, role, content, created_at } as CallExchange)),
67	      } satisfies CallCard,
68	    };
69	  });
70	  return { hidden, items };
71	}
72	
73	const parseTasks = (tasks: unknown) => z.array(callTaskSchema).catch([]).parse(tasks);
