7	const cursorSchema = z.object({ created_at: z.iso.datetime({ offset: true }), id: z.uuid() });
8	export type HistoryMessage = { id: string; role: string; content: string; created_at: string; plan?: string[]; tools?: SavedToolStep[]; attachments?: ChatAttachment[]; spoken?: boolean; call?: CallCard };
9	export type SavedToolStep = { name: string; state: "done"; input?: unknown; output?: string };
10	export type HistoryThread = { id: string; title: string; created_at: string };
11	const THREAD_PAGE = 30;
12	// Small first page: older messages load on demand, so opening a long chat stays fast.
13	const MESSAGE_PAGE = 30;
14	// Saved tool outputs can be tens of KB each; history shows a preview, the full record stays in chat_requests.
15	const OUTPUT_PREVIEW = 2000;
16	const preview = (output?: string) => output && output.length > OUTPUT_PREVIEW ? `${output.slice(0, OUTPUT_PREVIEW)}\n… (truncated)` : output;
17	// A chat run outlives its tab for up to the chat route's maxDuration (300 s); an older "running" row was cut off, not working.
18	const RUN_WINDOW_MS = 6 * 60_000;
19	export const conversationTitleSchema = z.string().trim().min(1).max(120);
