21	function before(value?: string) {
22	  if (!value) return null;
23	  try { return cursorSchema.parse(JSON.parse(value)); } catch { throw new Error("Invalid history cursor"); }
24	}
25	function cursor(row: { id: string; created_at: string }) { return JSON.stringify({ id: row.id, created_at: row.created_at }); }
26	// ponytail: LIKE wildcards are escaped; PostgREST also treats * as %, so it becomes a one-character wildcard.
27	function likePattern(query: string) { return `%${query.replace(/[\\%_]/g, "\\$&").replaceAll("*", "_")}%`; }
28	
29	/** Newest-first saved chats, keyset-paged; `query` searches titles and message text instead. */
30	export async function loadThreads(supabase: SupabaseClient, workspace: string, threadsBefore?: string, query?: string) {
31	  // An artifact's chat lives on the artifact's page, not in the chat list.
32	  const live = () => supabase.from("conversations").select("id,title,created_at").eq("workspace_id", workspace).is("deleted_at", null).is("artifact_id", null);
33	  const q = query?.trim().slice(0, 100);
34	  if (q) {
35	    const pattern = likePattern(q);
36	    const [titles, hits] = await Promise.all([
37	      live().ilike("title", pattern).order("created_at", { ascending: false }).limit(THREAD_PAGE),
38	      supabase.from("messages").select("conversation_id").eq("workspace_id", workspace).ilike("content", pattern).order("created_at", { ascending: false }).limit(200),
39	    ]);
40	    if (titles.error || hits.error) throw new Error("Could not search conversations. Try again.");
41	    const known = new Set((titles.data ?? []).map(row => row.id));
42	    const extra = [...new Set((hits.data ?? []).map(row => row.conversation_id as string))].filter(id => !known.has(id)).slice(0, THREAD_PAGE);
43	    const matched = extra.length ? await live().in("id", extra) : { data: [], error: null };
44	    if (matched.error) throw new Error("Could not search conversations. Try again.");
45	    const threads = [...(titles.data ?? []), ...(matched.data ?? [])]
46	      .sort((a, b) => b.created_at.localeCompare(a.created_at)).slice(0, THREAD_PAGE) as HistoryThread[];
47	    return { threads, threadsCursor: null };
48	  }
49	  const tc = before(threadsBefore);
50	  let tq = live().order("created_at", { ascending: false }).order("id", { ascending: false });
51	  if (tc) tq = tq.or(`created_at.lt.${tc.created_at},and(created_at.eq.${tc.created_at},id.lt.${tc.id})`);
52	  const { data, error } = await tq.limit(THREAD_PAGE + 1);
53	  if (error) throw new Error("Could not load conversations. Try again.");
54	  const threads = (data ?? []).slice(0, THREAD_PAGE) as HistoryThread[];
55	  return { threads, threadsCursor: (data?.length ?? 0) > THREAD_PAGE ? cursor(threads[threads.length - 1]) : null };
56	}
