58	/** One owned conversation and a newest page of its messages (oldest first), loaded in parallel. */
59	export async function loadConversation(supabase: SupabaseClient, workspace: string, id: string, messagesBefore?: string) {
60	  const mc = before(messagesBefore);
61	  if (!z.uuid().safeParse(id).success) throw new Error("Conversation unavailable");
62	  let mq = supabase.from("messages").select("id,role,content,created_at,request_id,reply_to,attachments,context").eq("workspace_id", workspace).eq("conversation_id", id).order("created_at", { ascending: false }).order("id", { ascending: false });
63	  if (mc) mq = mq.or(`created_at.lt.${mc.created_at},and(created_at.eq.${mc.created_at},id.lt.${mc.id})`);
64	  const [conversation, page, run, stubs] = await Promise.all([
65	    supabase.from("conversations").select("id,title,created_at").eq("workspace_id", workspace).eq("id", id).is("deleted_at", null).maybeSingle(),
66	    mq.limit(MESSAGE_PAGE + 1),
67	    // A request still working in the background, so a returning user sees it as in progress.
68	    mc ? null : supabase.from("chat_requests").select("id,created_at").eq("workspace_id", workspace).eq("conversation_id", id).eq("status", "running")
69	      .order("created_at", { ascending: false }).limit(1).maybeSingle(),
70	    callStubs(supabase, workspace, id),
71	  ]);
72	  if (conversation.error) throw new Error("Could not load conversation. Try again.");
73	  if (!conversation.data) throw new Error("Conversation unavailable. It may be missing or belong to another workspace.");
74	  if (page.error) throw new Error("Could not load messages. Try again.");
75	  const rows = (page.data ?? []).slice(0, MESSAGE_PAGE) as (HistoryMessage & { request_id?: string | null; reply_to?: string | null; context?: unknown })[];
76	  const messagesCursor = (page.data?.length ?? 0) > MESSAGE_PAGE ? cursor(rows[rows.length - 1]) : null;
77	  // A finished call shows as one card at the time it ended; the messages its requests made move inside it.
78	  const calls = await loadCalls(supabase, workspace, id, stubs, { requestIds: rows.flatMap(row => row.request_id ?? row.reply_to ?? []),
79	    from: messagesCursor ? rows[rows.length - 1].created_at : undefined, to: mc?.created_at });
80	  const visible = rows.filter(row => !calls.hidden.has((row.request_id ?? row.reply_to) as string));

