5	type Context = { params: Promise<{ id: string }> };
6	const headers = { "Cache-Control": "no-store" };
7	
8	async function owned({ params }: Context) {
9	  const { id } = await params;
10	  if (!z.uuid().safeParse(id).success) return Response.json({ error: "Conversation unavailable" }, { status: 404 });
11	  try { return { id, context: await requireWorkspace() }; }
12	  catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
13	}
14	
15	export async function GET(request: Request, route: Context) {
16	  const found = await owned(route);
17	  if (found instanceof Response) return found;
18	  const { id, context } = found;
19	  try {
20	    return Response.json(await loadConversation(context.supabase, context.workspace.id, id, new URL(request.url).searchParams.get("messagesBefore") ?? undefined), { headers });
21	  } catch (cause) {
22	    return Response.json({ error: cause instanceof Error ? cause.message : "Could not load conversation" }, { status: 400, headers });
23	  }
24	}
25	
26	export async function PATCH(request: Request, route: Context) {
27	  const found = await owned(route);
28	  if (found instanceof Response) return found;
29	  const { id, context } = found;
30	  const parsed = z.object({ title: conversationTitleSchema }).strict().safeParse(await request.json().catch(() => null));
31	  if (!parsed.success) return Response.json({ error: "Enter a title of 1 to 120 characters" }, { status: 400 });
32	  const result = await context.supabase.from("conversations").update({ title: parsed.data.title })
33	    .eq("workspace_id", context.workspace.id).eq("id", id).is("deleted_at", null).select("id,title,created_at").maybeSingle();
34	  if (result.error) return Response.json({ error: "Could not rename conversation. Try again." }, { status: 500 });
35	  if (!result.data) return Response.json({ error: "Conversation unavailable" }, { status: 404 });
36	  return Response.json(result.data);
37	}
38	
39	/** Soft delete: the chat leaves every list, while requests, audited edits and evidence stay intact. */
40	export async function DELETE(_request: Request, route: Context) {
41	  const found = await owned(route);
42	  if (found instanceof Response) return found;
43	  const { id, context } = found;
44	  const result = await context.supabase.from("conversations").update({ deleted_at: new Date().toISOString() })
45	    .eq("workspace_id", context.workspace.id).eq("id", id).is("deleted_at", null).select("id").maybeSingle();
46	  if (result.error) return Response.json({ error: "Could not delete conversation. Try again." }, { status: 500 });
47	  if (!result.data) return Response.json({ error: "Conversation unavailable" }, { status: 404 });
48	  return Response.json({ deleted: true });
49	}
