1	// Moneo runs its background jobs from the server process.
2	// Every job is safe to repeat: summaries and review recovery claim due work, and the syncs
3	// skip connections synced within the last day. Running hourly catches up after the
4	// computer was asleep or off.
5	export const CRON_JOBS = ["/api/cron/summaries", "/api/cron/reviews", "/api/cron/bank-sync", "/api/cron/scalable-sync"] as const;
6	const HOUR = 3_600_000, FIRST_RUN = 60_000;
7	
8	export async function runCronJobs(baseUrl: string, secret: string, fetcher: typeof fetch = fetch) {
9	  // One at a time, so the syncs don't compete with the summaries for the database.
10	  for (const path of CRON_JOBS) {
11	    try {
12	      const response = await fetcher(new URL(path, baseUrl), { headers: { authorization: `Bearer ${secret}` }, signal: AbortSignal.timeout(300_000) });
13	      // 503 means the feature isn't set up (no bank or Scalable keys); stay quiet about it.
14	      if (!response.ok && response.status !== 503) console.warn(`Scheduled job ${path} returned ${response.status}`);
15	    } catch (error) {
16	      console.warn(`Scheduled job ${path} failed`, error instanceof Error ? error.message : error);
17	    }
18	  }
19	}
20	
21	export function startScheduler(env: NodeJS.ProcessEnv = process.env) {
22	  const secret = env.CRON_SECRET;
23	  if (!secret) return null;
24	  const baseUrl = `http://127.0.0.1:${env.PORT ?? 3000}`;
25	  let running = false;
26	  const tick = async () => {
27	    if (running) return;
28	    running = true;
29	    try { await runCronJobs(baseUrl, secret); } finally { running = false; }
30	  };
31	  const first = setTimeout(tick, FIRST_RUN);
32	  const hourly = setInterval(tick, HOUR);
33	  first.unref(); hourly.unref();
34	  return () => { clearTimeout(first); clearInterval(hourly); };
35	}
